+public class BuilderDefaultsRuntime {
+	public static void main(String[] args) {
+		BuilderDefaultsGenericsInInitializer defaults = BuilderDefaultsGenericsInInitializer.builder().build();
+		assertValue("42A", defaults.foo);
+		assertValue("42A", defaults.bar);
+		BuilderDefaultsGenericsInInitializer custom = BuilderDefaultsGenericsInInitializer.builder().foo("custom").bar(null).build();
+		assertValue("custom", custom.foo);
+		assertValue(null, custom.bar);
+		BuilderDefaultsGenericsInInitializer.SuperBuilderDefaults superDefaults = BuilderDefaultsGenericsInInitializer.SuperBuilderDefaults.builder().build();
+		assertValue("42A", superDefaults.foo);
+		assertValue("42A", superDefaults.bar);
+		BuilderDefaultsGenericsInInitializer.SuperBuilderDefaults superCustom = BuilderDefaultsGenericsInInitializer.SuperBuilderDefaults.builder().foo("custom").bar(null).build();
+		assertValue("custom", superCustom.foo);
+		assertValue(null, superCustom.bar);
+	}
+
+	private static void assertValue(String expected, String actual) {
+		if (expected == null ? actual != null : !expected.equals(actual)) throw new AssertionError("Expected " + expected + ", got " + actual);
+	}
+}
